const langs = ['ja', 'de', 'fr', 'es', 'pt', 'it', 'ko', 'nl', 'pl'];
const en = JSON.parse(fs.readFileSync('src/i18n/translations/en.json', 'utf8'));

langs.forEach(lang => {
  const filePath = `src/i18n/translations/${lang}.json`;
  const data = JSON.parse(fs.readFileSync(filePath, 'utf8'));
  const trans = translations[lang];
  let updated = 0;

  Object.keys(trans).forEach(key => {
    if (data[key] === undefined || data[key] === en[key]) {
      data[key] = trans[key];
      updated++;
    }
  });

  fs.writeFileSync(filePath, JSON.stringify(data, null, 2) + '\n', 'utf8');
  console.log(`${lang}: ${updated} keys updated`);
});

